1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * First step of {@code POST /api/owners}: rejects a request that is missing or blank in any of
13	 * firstName, lastName, address, city or telephone with a 400 listing every offending field.
14	 *
15	 * <p>Binds the body once (no {@code @Valid}, so the missing-field check owns the 400 rather than
16	 * bean validation) and republishes it as a variable for the later {@link BuildOwner} step.
17	 */
18	public class RequireOwnerFields {
19	
20	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
21	            throws MissingOwnerFieldsException {
22	        List<String> missing = new ArrayList<>();
23	        requireText("firstName", request.getFirstName(), missing);
24	        requireText("lastName", request.getLastName(), missing);
25	        requireAddress(request.getAddress(), missing);
26	        requireText("city", request.getCity(), missing);
27	        requireText("telephone", request.getTelephone(), missing);
28	        if (!missing.isEmpty()) {
29	            throw new MissingOwnerFieldsException(missing);
30	        }
31	        validated.set(request);
32	    }
33	
34	    private static void requireText(String field, String value, List<String> missing) {
35	        if (value == null || value.isBlank()) {
36	            missing.add(field);
37	        }
38	    }
39	
40	    /**
41	     * The address is rejected when it is blank <em>after</em> normalization, so a value that
42	     * collapses to nothing is treated the same as a missing one.
43	     */
44	    private static void requireAddress(String value, List<String> missing) {
45	        if (AddressNormalizer.normalize(value).isEmpty()) {
46	            missing.add("address");
47	        }
48	    }
49	}
