5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Second step of {@code POST /api/owners}: normalises the telephone to E.164 form (strip spaces,
9	 * dashes and brackets; keep a leading {@code '+'} and country code, else assume {@code '+61'} and
10	 * drop a single leading {@code '0'}; require 8 to 15 digits after the {@code '+'}). The E.164 value
11	 * is written back onto the (shared) request DTO so it is stored and returned as {@code telephone};
12	 * anything that cannot form valid E.164 is rejected 400 via {@link InvalidTelephoneException}.
13	 */
14	public class NormalizeOwnerTelephone {
15	
16	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
17	        String e164 = E164Telephone.normalize(request.getTelephone());
18	        if (e164 == null) {
19	            throw new InvalidTelephoneException(request.getTelephone());
20	        }
21	        request.setTelephone(e164);
22	    }
23	}
