1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.regex.Pattern;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
8	
9	/**
10	 * Normalises the optional owner {@code email}. Email is optional, so a null/blank value is left
11	 * untouched and stored as absent. When present it must be a syntactically valid address; the
12	 * cleaned, lower-cased value is written back onto the (shared) request DTO so it is stored and
13	 * returned as {@code email}. Anything present but syntactically invalid is rejected 400 via
14	 * {@link InvalidEmailException}.
15	 */
16	public class NormalizeOwnerEmail {
17	
18	    /**
19	     * A pragmatic syntactic check: a non-empty local part, a single {@code @}, and a domain with at
20	     * least one dot-separated label ending in a letters-only top-level label of length 2+.
21	     */
22	    private static final Pattern EMAIL = Pattern.compile(
23	            "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");
24	
25	    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
26	        String email = request.getEmail();
27	        if (email == null || email.isBlank()) {
28	            request.setEmail(null);
29	            return;
30	        }
31	        String trimmed = email.trim();
32	        if (!EMAIL.matcher(trimmed).matches()) {
33	            throw new InvalidEmailException(email);
34	        }
35	        request.setEmail(trimmed.toLowerCase());
36	    }
37	}
