16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String city = owner.getCity();
18	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
19	        String lastName = owner.getLastName();
20	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
21	        int sequence = (int) ownerRepository.findAll().stream()
22	            .filter(o -> city.equals(o.getCity()))
23	            .count() + 1;
24	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
