1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Normalises telephone numbers to <a href="https://en.wikipedia.org/wiki/E.164">E.164</a> form.
5	 *
6	 * <p>Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are kept
7	 * as given; otherwise country code {@code +61} is assumed and a single leading {@code '0'} is
8	 * dropped from the national digits. The result is a {@code '+'} followed by 8 to 15 digits, so
9	 * {@code "0412 345 678"} becomes {@code "+61412345678"}.
10	 */
11	final class E164Telephone {
12	
13	    private E164Telephone() {
14	    }
15	
16	    /**
17	     * Returns the E.164 form of {@code raw}, or {@code null} when it cannot form a valid E.164
18	     * number (non-digit content after stripping separators, or not 8 to 15 digits after the
19	     * {@code '+'}).
20	     */
21	    static String normalize(String raw) {
22	        if (raw == null) {
23	            return null;
24	        }
25	        // Strip spaces, dashes and brackets.
26	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
27	        String digits;
28	        if (cleaned.startsWith("+")) {
29	            // Keep the leading '+' and country code as given.
30	            digits = cleaned.substring(1);
31	        }
32	        else {
33	            // No country code: assume '+61' and drop a single leading '0' from the national digits.
34	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
35	            digits = "61" + national;
36	        }
37	        if (!digits.matches("\\d{8,15}")) {
38	            return null;
39	        }
40	        return "+" + digits;
41	    }
42	}
